def copy_customer_dates_to_deals(apps, schema_editor):
    """Existing deals were created together with their customer, so the
    customer's creation time is the deal's real creation time."""
    Deal = apps.get_model("crm", "Deal")
    for deal in Deal.objects.select_related("customer").iterator():
        deal.created_at = deal.customer.created_at
        deal.save(update_fields=["created_at"])


